package com.euvcraft.lithmod.mc.multiblock.scanner;
import com.euvcraft.lithmod.core.WaterTank;import com.euvcraft.lithmod.core.multiblock.BlockKind;import com.euvcraft.lithmod.mc.multiblock.utilities.UtilityFluids;
import net.neoforged.neoforge.transfer.ResourceHandler;import net.neoforged.neoforge.transfer.fluid.FluidResource;import net.neoforged.neoforge.transfer.transaction.TransactionContext;import java.util.Objects;
final class ScannerWaterHandler implements ResourceHandler<FluidResource>{final ScannerMemberBlockEntity port;final ScannerControllerBlockEntity owner;private final FluidResource fluid=FluidResource.of(UtilityFluids.ULTRAPURE_WATER.get());
 ScannerWaterHandler(ScannerMemberBlockEntity p,ScannerControllerBlockEntity o){port=p;owner=o;}
 private WaterTank live(){var level=owner.getLevel();if(level==null||level.isClientSide()||owner.isRemoved()||port.isRemoved()||port.getLevel()!=level||level.getBlockEntity(owner.getBlockPos())!=owner||level.getBlockEntity(port.getBlockPos())!=port||port.controller()!=owner||port.structureKind()!=BlockKind.WATER_INLET)return null;owner.revalidate();return owner.isFormed()&&owner.immersion()&&port.controller()==owner&&owner.members().contains(port.getBlockPos())?owner.pureWater:null;}
 private static void index(int i){Objects.checkIndex(i,1);}@Override public int size(){return 1;}@Override public FluidResource getResource(int i){index(i);var t=live();return t!=null&&t.amount()>0?fluid:FluidResource.EMPTY;}@Override public long getAmountAsLong(int i){index(i);var t=live();return t==null?0:t.amount();}@Override public long getCapacityAsLong(int i,FluidResource r){index(i);var t=live();return t!=null&&(r.isEmpty()||r.equals(fluid))?t.capacity():0;}@Override public boolean isValid(int i,FluidResource r){index(i);return r.equals(fluid)&&live()!=null;}
 @Override public int insert(int i,FluidResource r,int n,TransactionContext tx){index(i);Objects.requireNonNull(r);Objects.requireNonNull(tx);if(r.isEmpty()||n<0)throw new IllegalArgumentException();var t=live();if(t==null||!r.equals(fluid))return 0;int amount=t.fill(n,true);if(amount>0){owner.pureJournal.updateSnapshots(tx);t.fill(amount,false);}return amount;}
 @Override public int extract(int i,FluidResource r,int n,TransactionContext tx){index(i);Objects.requireNonNull(r);Objects.requireNonNull(tx);if(r.isEmpty()||n<0)throw new IllegalArgumentException();return 0;}
}
